def main():
    failures = []
    checked = 0
    for document in ROOT.rglob("*.md"):
        if set(document.relative_to(ROOT).parts) & EXCLUDED:
            continue
        content = document.read_text(encoding="utf-8")
        content = re.sub(r"```.*?```", "", content, flags=re.DOTALL)
        for raw in re.findall(r"\[[^\]]*\]\(([^\s)]+)(?:\s+[^)]*)?\)", content):
            parsed = urlsplit(raw.strip("<>"))
            if parsed.scheme or parsed.netloc or not parsed.path:
                continue
            target = document.parent / unquote(parsed.path)
            checked += 1
            if not target.exists():
                failures.append(f"{document.relative_to(ROOT)}: missing {raw}")
    if failures:
        raise SystemExit("\n".join(failures))
    print(f"Verified {checked} local Markdown targets (remote URLs and anchors excluded).")

def main():
    manifest = json.loads((ROOT / "evals/corpus-manifest.json").read_text())
    destination = ROOT / "data/corpus"
    destination.mkdir(parents=True, exist_ok=True)
    for doc in manifest["documents"]:
        request = urllib.request.Request(
            doc["download_url"], headers={"User-Agent": "DocAtlas-corpus-builder"}
        )
        with urllib.request.urlopen(request, timeout=30) as response:
            content = response.read(2_000_001)
        if len(content) > 2_000_000:
            raise ValueError("Document exceeds the download limit.")
        if hashlib.sha256(content).hexdigest() != doc["sha256"]:
            raise ValueError(f"Corpus checksum mismatch: {doc['filename']}")
        (destination / doc["filename"]).write_bytes(content)
        print(doc["filename"])
    (ROOT / "data/corpus-sources.json").write_text(
        json.dumps({d["filename"]: d["source_url"] for d in manifest["documents"]}, indent=2)
    )

STOPWORDS = set(
    "a an the is are was were how what when where why which can could would should do does did i we you it to of for in on and or with from my me this that please tell about".split()
)

def sufficient_evidence(question, hits, minimum_dense=0.55):
    terms = substantive_words(question)
    if not terms or not hits:
        return False
    for hit in hits:
        overlap = len(terms & substantive_words(hit["text"])) / len(terms)
        if overlap >= 0.5 or (hit.get("dense_score") or 0) >= minimum_dense:
            return True
    return False

class ProviderError(Exception):
    def __init__(self, message, code="invalid_citation"):
        super().__init__(message)
        self.code = code

def __init__(self, message, code="invalid_citation"):
    super().__init__(message)
    self.code = code

def validate_claims(payload, hits):
    """Verify source membership and verbatim quotation, not semantic entailment."""
    by_id = {hit["id"]: hit for hit in hits}
    claims = payload.get("claims") if isinstance(payload, dict) else None
    if not isinstance(claims, list) or not claims or len(claims) > 6:
        raise ProviderError("The model did not return valid supported claims.")
    result = []
    for claim in claims:
        if not isinstance(claim, dict) or set(claim) != {"text", "quote", "chunk_id"}:
            raise ProviderError("Malformed claim.")
        text, quote, chunk_id = (claim.get(key) for key in ("text", "quote", "chunk_id"))
        if not all(isinstance(v, str) for v in (text, quote, chunk_id)):
            raise ProviderError("Malformed claim.")
        hit = by_id.get(chunk_id)
        if (
            not hit
            or not 12 <= len(normalize_quote(quote)) <= 1600
            or not 1 <= len(text.strip()) <= 1600
        ):
            raise ProviderError("An answer contained an invalid citation.")
        if normalize_quote(quote) not in normalize_quote(hit["text"]):
            raise ProviderError("An answer quoted evidence that was not retrieved.")
        result.append({"text": text, "quote": quote, "chunk_id": chunk_id})
    return result

CLAIM_SCHEMA = {
    "type": "object",
    "additionalProperties": False,
    "properties": {
        "claims": {
            "type": "array",
            "maxItems": 6,
            "items": {
                "type": "object",
                "additionalProperties": False,
                "properties": {key: {"type": "string"} for key in ("text", "chunk_id", "quote")},
                "required": ["text", "chunk_id", "quote"],
            },
        }
    },
    "required": ["claims"],
}

def request_body(question, hits, settings):
    # UTF-8 byte budgeting is intentionally conservative for byte-level tokenizers.
    # It is a guard, not an exact tokenizer or a measured token count.
    budget = settings.llm_context_tokens - settings.llm_max_tokens - 512
    context = []
    for hit in hits:
        candidate = context + [{"chunk_id": hit["id"], "text": hit["text"]}]
        content = json.dumps(
            {"question": question, "untrusted_passages": candidate}, ensure_ascii=False
        )
        if len((SYSTEM_PROMPT + content).encode("utf-8")) <= budget:
            context = candidate
    if not context:
        raise ProviderError(
            "No complete source passage fits the model context. Increase context size or reduce output tokens in Model setup.",
            "context_budget",
        )
    response_format = {"type": "json_object"}
    if settings.llm_format == "json_schema":
        response_format = {
            "type": "json_schema",
            "json_schema": {
                "name": "docatlas_answer",
                "strict": True,
                "schema": CLAIM_SCHEMA,
            },
        }
    return {
        "model": settings.llm_model,
        "temperature": 0,
        "max_tokens": settings.llm_max_tokens,
        "messages": [
            {"role": "system", "content": SYSTEM_PROMPT},
            {
                "role": "user",
                "content": json.dumps(
                    {"question": question, "untrusted_passages": context}, ensure_ascii=False
                ),
            },
        ],
        "response_format": response_format,
    }, [h for h in hits if h["id"] in {c["chunk_id"] for c in context}]

def parse_generation(data, supplied_hits):
    try:
        choice = data["choices"][0]
        if choice.get("finish_reason") == "length":
            raise ProviderError(
                "The model response was truncated. Increase output tokens in Model setup.",
                "output_truncated",
            )
        payload = json.loads(choice["message"]["content"])
        if isinstance(payload, dict) and payload.get("claims") == []:
            raise ModelAbstention
        claims = validate_claims(payload, supplied_hits)
        usage = data.get("usage", {})
        if not isinstance(usage, dict):
            usage = {}
        return claims, {
            k: v
            for k, v in usage.items()
            if k in {"prompt_tokens", "completion_tokens", "total_tokens"} and isinstance(v, int)
        }
    except (ValueError, KeyError, IndexError, TypeError, AttributeError) as exc:
        raise ProviderError(
            "The model returned incompatible output. Check its JSON response format.",
            "invalid_output",
        ) from exc

def generate(question, hits, settings, client=None):
    body, supplied_hits = request_body(question, hits, settings)
    headers = {"Authorization": f"Bearer {settings.llm_key}"} if settings.llm_key else {}
    own_client = client is None
    client = client or httpx.Client(
        timeout=httpx.Timeout(settings.llm_timeout, connect=5),
        follow_redirects=False,
        trust_env=False,
    )
    try:
        with client.stream(
            "POST", settings.llm_url + "/chat/completions", headers=headers, json=body
        ) as response:
            response.raise_for_status()
            parts, size = [], 0
            for part in response.iter_bytes():
                size += len(part)
                if size > 256_000:
                    raise ProviderError(
                        "Provider output exceeds the response limit.", "output_limit"
                    )
                parts.append(part)
        return parse_generation(json.loads(b"".join(parts)), supplied_hits)
    except httpx.HTTPError as exc:
        failure = provider_failure(exc)
        raise ProviderError(failure.message, failure.code) from exc
    except ValueError as exc:
        raise ProviderError("The provider returned invalid JSON.", "invalid_output") from exc
    finally:
        if own_client:
            client.close()

async def generate_async(question, hits, settings, client=None):
    body, supplied_hits = request_body(question, hits, settings)
    headers = {"Authorization": f"Bearer {settings.llm_key}"} if settings.llm_key else {}
    own_client = client is None
    client = client or httpx.AsyncClient(
        timeout=httpx.Timeout(settings.llm_timeout, connect=5),
        follow_redirects=False,
        trust_env=False,
    )
    try:
        async with client.stream(
            "POST", settings.llm_url + "/chat/completions", headers=headers, json=body
        ) as response:
            response.raise_for_status()
            parts, size = [], 0
            async for part in response.aiter_bytes():
                size += len(part)
                if size > 256_000:
                    raise ProviderError(
                        "Provider output exceeds the response limit.", "output_limit"
                    )
                parts.append(part)
        return parse_generation(json.loads(b"".join(parts)), supplied_hits)
    except httpx.HTTPError as exc:
        failure = provider_failure(exc)
        raise ProviderError(failure.message, failure.code) from exc
    except ValueError as exc:
        raise ProviderError("The provider returned invalid JSON.", "invalid_output") from exc
    finally:
        if own_client:
            await client.aclose()

def preflight(question, hits, settings):
    if not sufficient_evidence(question, hits, settings.min_dense_score):
        return {
            "status": "insufficient_evidence",
            "message": "I couldn't find enough supporting evidence in this library.",
            "claims": [],
            "usage": {},
        }
    if not settings.llm_url or not settings.llm_model:
        return {
            "status": "evidence_only",
            "message": "Relevant source passages found. Open Model setup to connect LM Studio or an optional API provider.",
            "claims": [],
            "usage": {},
        }
    return None

def success(claims, usage):
    return {
        "status": "answered",
        "message": "Draft answer: source IDs and quotes were checked, but claim accuracy was not verified. Inspect each quote before relying on the answer.",
        "verification": {
            "source_membership": True,
            "quotes": True,
            "semantic_support": "not_verified",
        },
        "claims": claims,
        "usage": usage,
    }

def failure_result(exc):
    if isinstance(exc, ModelAbstention):
        return {
            "status": "insufficient_evidence",
            "message": "The retrieved passages do not support an answer to this question.",
            "claims": [],
            "usage": {},
        }
    return {
        "status": "generation_unavailable",
        "message": str(exc),
        "error_code": exc.code,
        "claims": [],
        "usage": {},
    }

def answer(question, hits, settings, client=None):
    early = preflight(question, hits, settings)
    if early:
        return early
    try:
        return success(*generate(question, hits, settings, client))
    except (ProviderError, ModelAbstention) as exc:
        return failure_result(exc)

async def answer_async(question, hits, settings):
    early = preflight(question, hits, settings)
    if early:
        return early
    try:
        return success(*await generate_async(question, hits, settings))
    except (ProviderError, ModelAbstention) as exc:
        return failure_result(exc)

def create_app(settings=None, encoder=None):
    settings = settings or Settings.from_env()
    if settings.embeddings not in {"bm25", "fastembed"}:
        raise ValueError("DOCATLAS_EMBEDDINGS must be bm25 or fastembed.")
    if settings.embeddings == "fastembed" and encoder is None:
        encoder = LocalEncoder(settings.embedding_model, settings.data_dir / "models")
    store = Store(settings.data_dir, encoder)
    jobs = JobQueue(store, settings)

    @asynccontextmanager
    async def lifespan(app):
        jobs.start()
        try:
            yield
        finally:
            await asyncio.to_thread(jobs.close)

    app = FastAPI(
        title="DocAtlas",
        version="1.0.0",
        docs_url=None,
        redoc_url=None,
        openapi_url=None,
        lifespan=lifespan,
    )
    app.state.jobs = jobs
    app.state.store = store
    app.state.settings = settings
    providers = ProviderManager(settings)
    app.state.providers = providers
    active_asks = {}
    pending_work = 0
    counters = Counter()
    durations = deque(maxlen=1000)
    windows = {}
    state_lock = threading.Lock()
    work_slots = asyncio.Semaphore(4)

    @asynccontextmanager
    async def work_slot():
        nonlocal pending_work
        if pending_work >= 12:
            raise HTTPException(
                503, "Workspace is busy. Try again shortly.", headers={"Retry-After": "5"}
            )
        pending_work += 1
        acquired = False
        try:
            try:
                await asyncio.wait_for(work_slots.acquire(), timeout=15)
                acquired = True
            except TimeoutError as exc:
                raise HTTPException(503, "Work queue timed out. Try again shortly.") from exc
            yield
        finally:
            pending_work -= 1
            if acquired:
                work_slots.release()

    @app.exception_handler(RequestValidationError)
    async def validation_error(request, exc):
        # Validation errors must not echo provider keys submitted in the request.
        return JSONResponse(
            {
                "detail": [
                    {"loc": e["loc"], "msg": e["msg"], "type": e["type"]} for e in exc.errors()
                ]
            },
            status_code=422,
        )

    @app.middleware("http")
    async def controls(request: Request, call_next):
        request_id = str(uuid.uuid4())
        start = time.perf_counter()
        if request.url.path.startswith("/api/"):
            if settings.api_key and not secrets.compare_digest(
                request.headers.get("x-api-key", ""), settings.api_key
            ):
                return JSONResponse(
                    {"detail": "A valid workspace API key is required."}, status_code=401
                )
            # Do not trust forwarded headers from arbitrary clients.
            client = request.client.host if request.client else "unknown"
            now = time.monotonic()
            with state_lock:
                for key in list(windows):
                    if not windows[key] or windows[key][-1] <= now - 60:
                        del windows[key]
                window = windows.setdefault(client, deque())
                while window and window[0] <= now - 60:
                    window.popleft()
                if len(window) >= settings.rate_limit:
                    return JSONResponse(
                        {"detail": "Rate limit reached. Try again shortly."},
                        status_code=429,
                        headers={"Retry-After": "60"},
                    )
                window.append(now)
            if request.method not in {"GET", "HEAD", "OPTIONS"}:
                # Same-origin web UI; API callers without Origin may use API keys.
                origin = request.headers.get("origin")
                if origin and origin != str(request.base_url).rstrip("/"):
                    return JSONResponse(
                        {"detail": "Cross-origin writes are not accepted."}, status_code=403
                    )
            raw_length = request.headers.get("content-length", "0")
            if (
                request.url.path in {"/api/documents", "/api/ingestion/jobs"}
                and request.method == "POST"
                and "content-length" not in request.headers
            ):
                return JSONResponse({"detail": "Uploads require Content-Length."}, status_code=411)
            try:
                if int(raw_length) > (settings.max_upload_mb + 1) * 1024 * 1024:
                    return JSONResponse({"detail": "Request too large."}, status_code=413)
            except ValueError:
                return JSONResponse({"detail": "Invalid Content-Length."}, status_code=400)
        request.state.request_id = request_id
        try:
            response = await call_next(request)
        except Exception:
            logger.exception("request_failed id=%s", request_id)
            response = JSONResponse(
                {"detail": "Unexpected server error.", "request_id": request_id}, status_code=500
            )
        elapsed = (time.perf_counter() - start) * 1000
        with state_lock:
            counters[f"http_{response.status_code}"] += 1
            durations.append(elapsed)
        response.headers.update(
            {
                "X-Request-ID": request_id,
                "X-Content-Type-Options": "nosniff",
                "Referrer-Policy": "no-referrer",
                "X-Frame-Options": "DENY",
                "Content-Security-Policy": "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'",
            }
        )
        if request.url.path.startswith("/api/"):
            response.headers["Cache-Control"] = "no-store"
        return response

    @app.get("/health")
    def health():
        with store.connect() as db:
            db.execute("SELECT 1")
        return {"status": "ok"}

    @app.get("/api/config")
    def config():
        return {
            "version": "1.0.0",
            "modes": ["bm25", "dense", "hybrid"] if encoder else ["bm25"],
            "default_mode": "hybrid" if encoder else "bm25",
            "generation": providers.public()["configured"],
            "provider": {
                k: v
                for k, v in providers.public().items()
                if k in {"kind", "model", "configured", "last_check", "privacy"}
            },
            "embedding_model": encoder.name if encoder else None,
            "max_upload_mb": settings.max_upload_mb,
        }

    def owner_only(request):
        # A shared library key is not authority to change a remote provider or read its settings.
        # Configuration is restricted to a client connected directly from the local machine.
        if request.url.hostname not in {"127.0.0.1", "localhost", "::1", "testserver", "test"}:
            raise HTTPException(403, "Model setup requires a local hostname.")
        if request.client and request.client.host not in {"127.0.0.1", "::1", "testclient"}:
            raise HTTPException(403, "Model setup is available only from this computer.")

    @app.get("/api/provider")
    def provider_config(request: Request):
        owner_only(request)
        return providers.public()

    @app.put("/api/provider")
    def save_provider(value: ProviderInput, request: Request):
        owner_only(request)
        return providers.save(value)

    @app.post("/api/provider/models")
    async def provider_models(value: ProviderInput, request: Request):
        owner_only(request)
        try:
            async with work_slot():
                return {"models": await providers.models(value)}
        except ProviderFailure as exc:
            return JSONResponse({"detail": exc.message, "code": exc.code}, status_code=502)

    @app.post("/api/provider/check")
    async def provider_check(value: ProviderInput, request: Request):
        owner_only(request)
        value = providers.resolved(value)
        if value.kind == "disabled" or not value.model:
            raise HTTPException(422, "Select a model before testing generation.")
        snapshot = replace(
            settings,
            llm_url=value.base_url,
            llm_model=value.model,
            llm_key=value.api_key or "",
            llm_kind=value.kind,
            llm_format=value.response_format,
            llm_timeout=value.timeout_seconds,
            llm_context_tokens=value.context_tokens,
            llm_max_tokens=value.max_output_tokens,
        )
        probe = [
            {
                "id": "connection-probe",
                "text": "The DocAtlas connection test uses the code word atlas-ready.",
            }
        ]
        start = time.perf_counter()
        try:
            async with work_slot():
                claims, usage = await asyncio.wait_for(
                    generate_async(
                        "What code word does the DocAtlas connection test use?", probe, snapshot
                    ),
                    timeout=value.timeout_seconds,
                )
            if not any("atlas-ready" in c["text"] for c in claims):
                raise ProviderError(
                    "The model did not answer the connection test correctly.", "probe_failed"
                )
            check = {
                "status": "ready",
                "model": value.model,
                "latency_ms": round((time.perf_counter() - start) * 1000, 2),
                "checked_at": datetime.now(UTC).isoformat(),
                "message": "Live generation and citation-format checks passed. Answer quality still requires evaluation.",
            }
            with providers.lock:
                current = providers.snapshot()
                if (
                    current.llm_url,
                    current.llm_model,
                    current.llm_format,
                    current.llm_key,
                    current.llm_timeout,
                    current.llm_context_tokens,
                    current.llm_max_tokens,
                ) == (
                    snapshot.llm_url,
                    snapshot.llm_model,
                    snapshot.llm_format,
                    snapshot.llm_key,
                    snapshot.llm_timeout,
                    snapshot.llm_context_tokens,
                    snapshot.llm_max_tokens,
                ):
                    providers.last_check = check
            return {**check, "usage": usage}
        except TimeoutError:
            return JSONResponse(
                {
                    "detail": "The connection test timed out. Load the model and try again.",
                    "code": "provider_timeout",
                },
                status_code=504,
            )
        except ProviderError as exc:
            return JSONResponse({"detail": str(exc), "code": exc.code}, status_code=502)
        except ModelAbstention:
            return JSONResponse(
                {"detail": "The model abstained on the connection test.", "code": "probe_failed"},
                status_code=502,
            )

    @app.get("/api/documents")
    def documents():
        return {"documents": store.list_documents(), "fingerprint": store.fingerprint()}

    @app.get("/api/documents/{document_id}")
    def document(document_id: str):
        result = store.document(document_id)
        if not result:
            raise HTTPException(404, "Document not found.")
        return result

    @app.post("/api/documents", status_code=201)
    async def upload(file: Annotated[UploadFile, File()], source: Annotated[str, Form()] = ""):
        limit = settings.max_upload_mb * 1024 * 1024
        data = await file.read(limit + 1)
        await file.close()
        if len(data) > limit:
            raise HTTPException(413, "File exceeds the upload limit.")
        if len(source) > 2000:
            raise HTTPException(422, "Source URL is too long.")
        async with work_slot():
            try:
                return await asyncio.to_thread(store.ingest, file.filename or "", data, source)
            except ValueError as exc:
                raise HTTPException(422, str(exc)) from exc

    @app.post("/api/ingestion/jobs", status_code=202)
    async def enqueue(file: Annotated[UploadFile, File()], source: Annotated[str, Form()] = ""):
        limit = settings.max_upload_mb * 1024 * 1024
        try:
            data = bytearray()
            while part := await file.read(min(65536, limit + 1 - len(data))):
                data.extend(part)
                if len(data) > limit:
                    raise HTTPException(413, "File exceeds the upload limit.")
            return await asyncio.to_thread(jobs.submit, file.filename or "", bytes(data), source)
        except ValueError as exc:
            raise HTTPException(422, str(exc)) from exc
        finally:
            await file.close()

    @app.get("/api/ingestion/jobs")
    def ingestion_jobs():
        return {"jobs": jobs.list()}

    @app.get("/api/ingestion/jobs/{job_id}")
    def ingestion_job(job_id: uuid.UUID):
        job = jobs.get(str(job_id))
        if not job:
            raise HTTPException(404, "Ingestion job not found.")
        return job

    @app.delete("/api/ingestion/jobs/{job_id}")
    def cancel_ingestion(job_id: uuid.UUID):
        if not jobs.get(str(job_id)):
            raise HTTPException(404, "Ingestion job not found.")
        if not jobs.cancel(str(job_id)):
            raise HTTPException(409, "This job has already finished.")
        return {"status": "cancellation_requested"}

    @app.post("/api/ingestion/jobs/{job_id}/retry")
    def retry_ingestion(job_id: uuid.UUID):
        try:
            return jobs.retry(str(job_id))
        except ValueError as exc:
            raise HTTPException(409, str(exc)) from exc

    @app.delete("/api/documents/{document_id}")
    def delete(document_id: str):
        existing = store.document(document_id)
        if existing:
            for job in jobs.list():
                if job["filename"] == existing["filename"]:
                    jobs.cancel(job["id"])
        if not store.delete(document_id):
            raise HTTPException(404, "Document not found.")
        return {"status": "deleted"}

    def run_search(query):
        if not query.question.strip():
            raise HTTPException(422, "Question must contain text.")
        try:
            return store.search(query.question, query.mode, query.k, query.document_id)
        except ValueError as exc:
            raise HTTPException(422, str(exc)) from exc

    @app.post("/api/search")
    async def search(query: Query, request: Request):
        start = time.perf_counter()
        async with work_slot():
            hits = await asyncio.to_thread(run_search, query)
        return {
            "hits": hits,
            "mode": query.mode,
            "latency_ms": round((time.perf_counter() - start) * 1000, 2),
            "request_id": request.state.request_id,
        }

    @app.post("/api/ask")
    async def ask(query: Query, request: Request):
        start = time.perf_counter()
        operation_id = str(query.operation_id or uuid.uuid4())
        if operation_id in active_asks:
            raise HTTPException(409, "This question is already running.")
        snapshot = providers.snapshot()

        async def execute():
            async with work_slot():
                hits = await asyncio.to_thread(run_search, query)
                try:
                    result = await asyncio.wait_for(
                        answer_async(
                            query.question,
                            hits,
                            replace(snapshot, llm_url="", llm_model="")
                            if query.answer_style == "evidence"
                            else snapshot,
                        ),
                        timeout=snapshot.llm_timeout,
                    )
                except TimeoutError:
                    result = {
                        "status": "generation_unavailable",
                        "error_code": "provider_timeout",
                        "message": "The model timed out. Source passages remain available. Check Model setup.",
                        "claims": [],
                        "usage": {},
                    }
                if query.answer_style == "evidence" and result["status"] == "evidence_only":
                    result["message"] = "Source excerpts selected. No generation model was called."
                return hits, result

        task = asyncio.create_task(execute())
        active_asks[operation_id] = task
        try:
            hits, result = await task
        except asyncio.CancelledError:
            return JSONResponse(
                {
                    "status": "cancelled",
                    "message": "Request cancelled. The model server may finish work already dispatched.",
                },
                status_code=499,
            )
        finally:
            active_asks.pop(operation_id, None)
        with state_lock:
            counters[result["status"]] += 1
        return {
            **result,
            "hits": hits,
            "mode": query.mode,
            "operation_id": operation_id,
            "provider": {"kind": snapshot.llm_kind, "model": snapshot.llm_model},
            "latency_ms": round((time.perf_counter() - start) * 1000, 2),
            "request_id": request.state.request_id,
        }

    @app.delete("/api/requests/{operation_id}")
    async def cancel_request(operation_id: uuid.UUID):
        task = active_asks.get(str(operation_id))
        if not task:
            raise HTTPException(404, "The request has already finished or is not running.")
        task.cancel()
        return {"status": "cancellation_requested"}

    @app.post("/api/feedback", status_code=201)
    def feedback(value: Feedback):
        store.save_feedback(str(value.request_id), value.helpful, value.note)
        return {"status": "saved"}

    @app.get("/api/readiness")
    def readiness():
        with store.connect() as db:
            integrity = db.execute("PRAGMA quick_check").fetchone()[0]
            chunks = db.execute("SELECT COUNT(*) FROM chunks").fetchone()[0]
            indexed = db.execute("SELECT COUNT(*) FROM search").fetchone()[0]
            missing = db.execute(
                "SELECT COUNT(*) FROM chunks c LEFT JOIN search s ON s.chunk_id=c.id WHERE s.chunk_id IS NULL"
            ).fetchone()[0]
            states = dict(db.execute("SELECT state,COUNT(*) FROM ingestion_jobs GROUP BY state"))
        worker_running = bool(jobs.thread and jobs.thread.is_alive())
        healthy = integrity == "ok" and chunks == indexed and not missing and worker_running
        return JSONResponse(
            {
                "status": "ready" if healthy else "degraded",
                "database": integrity,
                "chunks": chunks,
                "indexed": indexed,
                "missing_index_entries": missing,
                "ingestion_jobs": states,
                "ingestion_worker": "running" if worker_running else "stopped",
                "model": "tested" if providers.public()["last_check"] else "untested",
                "answer_quality": "not_certified",
            },
            status_code=200 if healthy else 503,
        )

    @app.get("/api/metrics")
    def metrics():
        with state_lock:
            ordered = sorted(durations)
            return {
                "counts": dict(counters),
                "recent_requests": len(ordered),
                "p95_ms": round(ordered[min(int(len(ordered) * 0.95), len(ordered) - 1)], 2)
                if ordered
                else 0,
            }

    @app.get("/api/openapi.json")
    def schema():
        return app.openapi()

    app.mount("/", StaticFiles(directory=Path(__file__).parent / "static", html=True), name="web")
    return app

def main():
    parser = argparse.ArgumentParser(description="DocAtlas documentation workspace")
    commands = parser.add_subparsers(dest="command", required=True)
    serve = commands.add_parser("serve", help="Run the web application")
    serve.add_argument("--host", default="127.0.0.1")
    serve.add_argument("--port", type=int, default=8000)
    ingest = commands.add_parser("ingest", help="Index local documents")
    ingest.add_argument("paths", nargs="+", type=Path)
    ingest.add_argument(
        "--manifest", type=Path, help="Optional filename-to-source-URL JSON mapping"
    )
    ev = commands.add_parser("eval", help="Evaluate retrieval against a labeled JSONL dataset")
    ev.add_argument("dataset", type=Path)
    ev.add_argument("--modes", nargs="+", choices=["bm25", "dense", "hybrid"], default=["bm25"])
    ev.add_argument("--k", type=int, default=5)
    ev.add_argument("--output", type=Path, default=Path("data/eval-report.json"))
    ev.add_argument("--baseline", type=Path)
    ev.add_argument("--tolerance", type=float, default=0.01)
    args = parser.parse_args()
    settings = Settings.from_env()
    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(name)s %(message)s")
    if args.command == "serve":
        if args.host not in {"127.0.0.1", "localhost", "::1"} and not settings.api_key:
            parser.error("Set DOCATLAS_API_KEY before listening beyond localhost.")
        import uvicorn

        from .api import create_app

        uvicorn.run(create_app(settings), host=args.host, port=args.port)
        return
    if settings.embeddings not in {"bm25", "fastembed"}:
        parser.error("DOCATLAS_EMBEDDINGS must be bm25 or fastembed.")
    encoder = (
        LocalEncoder(settings.embedding_model, settings.data_dir / "models")
        if settings.embeddings == "fastembed"
        else None
    )
    store = Store(settings.data_dir, encoder)
    if args.command == "ingest":
        manifest = json.loads(args.manifest.read_text()) if args.manifest else {}
        files = []
        for path in args.paths:
            files.extend(
                sorted(p for p in path.rglob("*") if p.is_file() and p.suffix.lower() in SUPPORTED)
                if path.is_dir()
                else [path]
            )
        if len({p.name for p in files}) != len(files):
            parser.error(
                "Duplicate filenames in input. Rename files to keep source identity unambiguous."
            )
        if not files:
            parser.error("No supported documents found.")
        for path in files:
            if path.stat().st_size > settings.max_upload_mb * 1024 * 1024:
                parser.error(f"File too large: {path.name}")
            print(
                json.dumps(
                    {
                        "filename": path.name,
                        **store.ingest(path.name, path.read_bytes(), manifest.get(path.name, "")),
                    }
                )
            )
    elif args.command == "eval":
        if not 1 <= args.k <= 50:
            parser.error("k must be between 1 and 50.")
        report = evaluate(store, args.dataset, args.modes, args.k, settings.min_dense_score)
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(json.dumps(report, indent=2) + "\n")
        args.output.with_suffix(".md").write_text(markdown_report(report))
        print(markdown_report(report))
        if args.baseline:
            failures = regressions(json.loads(args.baseline.read_text()), report, args.tolerance)
            if failures:
                raise SystemExit("Regression gate failed:\n" + "\n".join(failures))

def score_case(case, hits):
    relevant = case.get("relevant", [])
    found = set()
    gains = []
    first = None
    for rank, hit in enumerate(hits, start=1):
        matched = {
            i
            for i, item in enumerate(relevant)
            if hit["filename"] == item["filename"]
            and normalize_quote(item["quote"]) in normalize_quote(hit["text"])
        }
        new = matched - found
        if matched and first is None:
            first = rank
        gains.append(1 if new else 0)
        found |= matched
    if not relevant:
        return {"recall": None, "mrr": None, "ndcg": None}
    dcg = sum(gain / math.log2(i + 2) for i, gain in enumerate(gains))
    ideal = sum(1 / math.log2(i + 2) for i in range(min(len(relevant), len(hits))))
    return {
        "recall": len(found) / len(relevant),
        "mrr": 1 / first if first else 0,
        "ndcg": dcg / ideal if ideal else 0,
    }

def load_cases(path: Path):
    cases = [json.loads(line) for line in path.read_text().splitlines() if line.strip()]
    ids = set()
    for case in cases:
        if not isinstance(case.get("id"), str) or case["id"] in ids:
            raise ValueError("Evaluation case ids must be unique strings.")
        ids.add(case["id"])
        if not isinstance(case.get("question"), str) or not case["question"].strip():
            raise ValueError("Each case needs a question.")
        if not isinstance(case.get("relevant"), list):
            raise ValueError("Each case needs a relevant array; use [] for unanswerable.")
        for item in case["relevant"]:
            if (
                not isinstance(item, dict)
                or not item.get("filename")
                or len(item.get("quote", "")) < 12
            ):
                raise ValueError(
                    "Relevant evidence needs a filename and a quote of at least 12 characters."
                )
    if not cases:
        raise ValueError("Evaluation dataset is empty.")
    return cases

def evaluate(store, dataset: Path, modes, k=6, minimum_dense=0.55):
    cases = load_cases(dataset)
    # Labels must exist in the corpus; otherwise recall numbers would be misleading.
    docs = {d["filename"]: store.document(d["id"]) for d in store.list_documents()}
    for case in cases:
        for item in case["relevant"]:
            doc = docs.get(item["filename"])
            if not doc or not any(
                normalize_quote(item["quote"]) in normalize_quote(p["text"])
                for p in doc["passages"]
            ):
                raise ValueError(f"Missing labeled evidence for {case['id']}: {item['filename']}")
    report = {
        "created_at": datetime.now(UTC).isoformat(),
        "dataset_sha256": hashlib.sha256(dataset.read_bytes()).hexdigest(),
        "corpus_fingerprint": store.fingerprint(),
        "embedding_model": store.encoder.name if store.encoder else None,
        "k": k,
        "min_dense_score": minimum_dense,
        "case_count": len(cases),
        "modes": {},
        "scope": "Retrieval and abstention only. Does not measure generated-answer accuracy.",
    }
    for mode in modes:
        results = []
        # Warm model once. Timings exclude startup/download cost, explicitly reported.
        store.search(cases[0]["question"], mode, k)
        for case in cases:
            start = time.perf_counter()
            hits = store.search(case["question"], mode, k)
            latency = (time.perf_counter() - start) * 1000
            abstained = not sufficient_evidence(case["question"], hits, minimum_dense)
            results.append(
                {
                    "id": case["id"],
                    "category": case.get("category", "general"),
                    "question": case["question"],
                    **score_case(case, hits),
                    "expected_abstention": not case["relevant"],
                    "abstained": abstained,
                    "latency_ms": round(latency, 3),
                    "retrieved_ids": [h["id"] for h in hits],
                }
            )

        def summary(rows):
            output = {}
            for metric in ("recall", "mrr", "ndcg"):
                values = [r[metric] for r in rows if r[metric] is not None]
                output[metric] = round(statistics.mean(values), 4) if values else None
            negatives = [r for r in rows if r["expected_abstention"]]
            positives = [r for r in rows if not r["expected_abstention"]]
            output["unanswerable_abstention_rate"] = (
                round(statistics.mean(r["abstained"] for r in negatives), 4) if negatives else None
            )
            output["answerable_false_abstention_rate"] = (
                round(statistics.mean(r["abstained"] for r in positives), 4) if positives else None
            )
            latencies = sorted(r["latency_ms"] for r in rows)
            output["warm_p95_ms"] = latencies[math.ceil(len(latencies) * 0.95) - 1]
            output["count"] = len(rows)
            return output

        report["modes"][mode] = {
            "summary": summary(results),
            "categories": {
                category: summary([r for r in results if r["category"] == category])
                for category in sorted({r["category"] for r in results})
            },
            "cases": results,
        }
    return report

def regressions(baseline, current, tolerance=0.01):
    if not 0 <= tolerance <= 1:
        raise ValueError("Tolerance must be between zero and one.")
    for key in ("dataset_sha256", "corpus_fingerprint", "k", "min_dense_score"):
        if baseline[key] != current[key]:
            raise ValueError(f"Incompatible evaluation reports: {key} differs.")
    failures = []
    for mode, old in baseline["modes"].items():
        if mode not in current["modes"]:
            failures.append(f"Missing mode: {mode}")
            continue
        new = current["modes"][mode]["summary"]
        for metric in ("recall", "mrr", "ndcg", "unanswerable_abstention_rate"):
            value = old["summary"].get(metric)
            if value is not None and (
                new.get(metric) is None or value - new[metric] > tolerance + 1e-9
            ):
                failures.append(f"{mode}: {metric} regressed from {value} to {new.get(metric)}")
        value = old["summary"].get("answerable_false_abstention_rate")
        if value is not None and (
            new.get("answerable_false_abstention_rate") is None
            or new["answerable_false_abstention_rate"] - value > tolerance + 1e-9
        ):
            failures.append(f"{mode}: answerable false abstention increased")
    return failures

class VisibleHTML(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts = []
        self.hidden = 0

    def handle_starttag(self, tag, attrs):
        if tag in {"script", "style", "noscript"}:
            self.hidden += 1
        if tag in {"p", "div", "br", "li", "h1", "h2", "h3", "pre"}:
            self.parts.append("\n")

    def handle_endtag(self, tag):
        if tag in {"script", "style", "noscript"}:
            self.hidden = max(0, self.hidden - 1)

    def handle_data(self, data):
        if not self.hidden:
            self.parts.append(data)

